from c4lib import *
import sys
H = int(sys.argv[1]) if len(sys.argv) > 1 else 2000
b = Board('C4_Rules', 'Rules', 1280, H, hdr=False)
css = '''<style>.rc{background:#fff;border:1px solid #E2E8F0;border-radius:14px;padding:20px 22px;display:flex;flex-direction:column;gap:12px;box-sizing:border-box}.rc h2{font-size:16px;font-weight:800}.rc li{font-size:13px;line-height:20px;color:#334155;margin-bottom:6px}.rc ul{padding-left:18px;margin:0}</style>'''
def card(t, inner): return f'<div class="rc"><h2>{t}</h2>{inner}</div>'
def ul(*it): return '<ul>' + ''.join(f'<li>{i}</li>' for i in it) + '</ul>'
cards = [
 card('Four levels, one question each', ul('<b>1 Context:</b> who uses the system and what it depends on? The system is one box.', '<b>2 Container:</b> what runs inside it? Apps, services, databases.', '<b>3 Component:</b> how is one container built? Controllers, handlers, clients.', '<b>4 Code:</b> classes. Not drawn here: use a UML class diagram.', 'One diagram answers one question. Never mix levels in one picture.')),
 card('Zooming', ul('Each level opens exactly one box of the level above and keeps its neighbours as they were.', 'The box you open becomes a dashed frame with its label on the bottom edge. Lines from above can then enter it without crossing the label.', 'Neighbours of the opened box stay as boxes of the level above: people and outside systems on level 2, containers on level 3.', 'Use the same name, tint and icon for the same thing on every level.')),
 card('Elements', ul('Five kinds: <b>person</b> (round corners), <b>software system</b>, <b>container</b>, <b>component</b>, and an <b>external system</b> (dashed border, grey).', 'Every box has a bold name, a line <span style="font-family:monospace">[Kind: technology]</span> and one sentence about its job.', 'Size: 280 × 132 (external boxes on a wide diagram 280 × 132 as well). Icon 40 px at top left, chosen by the noun.', 'Technology is in the type line, never in the name.')),
 card('Lines', ul('One arrow per relationship, from the one that starts the call to the receiver.', 'The label is a verb phrase (<i>Charges cards using</i>) and, on levels 2 and 3, the protocol (<i>HTTPS, JSON</i>).', 'Colours as elsewhere: main path blue, thick, animated; event or message violet, thin, slow; everything else ink.', 'Orthogonal, at most two bends. Leave 90 px of line for a label.')),
 card('Boundaries', ul('Level 1 has none: the system is a box. Level 2 draws the system as a frame, level 3 draws the container.', 'Frame tint follows the opened box. Label on the bottom edge: <i>Name [Software system]</i> or <i>Name [Container]</i>.', 'Parts in the frame sit at least 30 px inside it. Outside parties sit outside, with 240 px for a line that crosses.', 'A line crossing the frame is a call into or out of it: label it.')),
 card('Layout', ul('People on the top row, the thing being studied in the middle, what it depends on below or to the right.', 'Columns 520 px apart, rows 270 px apart. Gap between boxes on a labelled line at least 240 px.', 'Eight to fifteen boxes is right. Past that, zoom into a part instead of drawing more.', 'Do not draw a database as a component. It is a container.')),
 card('Animation', ul('One blue route per diagram: the story you tell (an order from the phone to the card network).', 'Violet is the event stream. Everything else is static.', 'The same route is blue on all three levels, so the zoom is easy to follow.', 'In draw.io each line has its own flow animation (flowAnimation=1) and its own duration: main route 500, event stream 1500. Checked in the draw.io viewer; SVG export not yet tested.')),
 card('What a plugin can rely on', ul('An element is: id, kind, name, technology, description, icon, tone and (optionally) the frame it sits in.', 'A relationship is: from, to, label, protocol and kind (call, main, event).', 'A diagram is: level, the opened element and its elements. The plugin finds the neighbours from the level above.', 'Layout uses rows and columns with the spacing above.')),
]
grid = f'<div style="display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px">{"".join(cards)}</div>'
b.raw(css + f'<div style="position:absolute;left:0;top:0;width:1280px;box-sizing:border-box;padding:64px;display:flex;flex-direction:column;gap:28px"><div style="display:flex;flex-direction:column;gap:8px"><div style="font-size:24px;font-weight:600">C4 · Rules</div><div style="font-size:13px;line-height:20px;color:#475569;max-width:900px">C4 draws one system at four levels of zoom. These are the conventions every C4 diagram follows, and that a plugin can rely on. The three examples next to it show one delivery platform at levels 1, 2 and 3.</div></div>{grid}</div>')
print(save8(b))
